// src/components/styles/ingest.scss
var ingest_default = ".ingest-page {\n  --ingest-ink: var(--kp-ink, #17201b);\n  --ingest-muted: var(--kp-muted, #69716c);\n  --ingest-border: var(--kp-border, #d9ddd8);\n  --ingest-paper: var(--kp-paper, #f7f7f3);\n  box-sizing: border-box;\n  min-height: 100vh;\n  padding: 38px 42px 56px;\n  overflow-x: hidden;\n  color: var(--ingest-ink);\n  background: var(--ingest-paper);\n}\n\n.ingest-page *, .ingest-page *::before, .ingest-page *::after {\n  box-sizing: border-box;\n}\n\n.ingest-page h1, .ingest-page h2, .ingest-page h3, .ingest-page p {\n  margin: 0;\n}\n\n.ingest-page button, .ingest-page select, .ingest-page input {\n  font: inherit;\n}\n\n.ingest-header {\n  display: flex;\n  align-items: end;\n  justify-content: space-between;\n  gap: 28px;\n  padding-bottom: 24px;\n  border-bottom: 2px solid var(--ingest-ink);\n}\n\n.ingest-eyebrow, .ingest-section-heading p, .ingest-publish p {\n  margin-bottom: 7px !important;\n  color: var(--ingest-muted);\n  font: 650 0.7rem/1.2 var(--codeFont);\n  letter-spacing: 0.13em;\n  text-transform: uppercase;\n}\n\n.ingest-header h1 {\n  font-size: clamp(2rem, 4vw, 3.7rem);\n  line-height: 0.95;\n  letter-spacing: -0.055em;\n}\n\n.ingest-intro {\n  max-width: 700px;\n  margin-top: 14px !important;\n  color: var(--ingest-muted);\n  font-size: 0.96rem;\n}\n\n.ingest-refresh, .ingest-file-action {\n  display: inline-flex;\n  min-height: 40px;\n  align-items: center;\n  justify-content: center;\n  padding: 8px 16px;\n  border: 1px solid var(--ingest-ink);\n  color: var(--ingest-ink);\n  background: transparent;\n  font-weight: 650;\n  cursor: pointer;\n}\n\n.ingest-refresh:hover, .ingest-file-action:hover {\n  color: var(--ingest-paper);\n  background: var(--ingest-ink);\n}\n\n.ingest-refresh:disabled {\n  opacity: 0.45;\n  cursor: wait;\n}\n\n.ingest-upload {\n  display: grid;\n  grid-template-columns: 74px minmax(0, 1fr) auto;\n  align-items: center;\n  gap: 22px;\n  margin-top: 22px;\n  padding: 22px;\n  border: 1px dashed #9ba29d;\n  background: color-mix(in srgb, var(--ingest-paper) 85%, white);\n  transition: border-color 120ms ease, background-color 120ms ease;\n}\n\n.ingest-upload.is-dragging {\n  border-color: var(--secondary);\n  background: color-mix(in srgb, var(--secondary) 7%, var(--ingest-paper));\n}\n\n.ingest-upload-index {\n  font: 700 1.55rem/1 var(--codeFont);\n  letter-spacing: -0.08em;\n}\n\n.ingest-upload h2 {\n  font-size: 1.15rem;\n}\n\n.ingest-upload-copy > p {\n  margin-top: 5px;\n  color: var(--ingest-muted);\n  font-size: 0.88rem;\n}\n\n.ingest-upload-copy .ingest-upload-note {\n  font-size: 0.75rem;\n}\n\n.ingest-upload input {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip: rect(0, 0, 0, 0);\n}\n\n.ingest-upload-status {\n  grid-column: 2/-1;\n  color: var(--ingest-muted);\n  font: 0.76rem/1.5 var(--codeFont);\n}\n\n.ingest-metrics {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  margin-top: 18px;\n  border-block: 1px solid var(--ingest-border);\n}\n\n.ingest-metrics > div {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 16px 18px;\n  border-right: 1px solid var(--ingest-border);\n}\n\n.ingest-metrics > div:last-child {\n  border-right: 0;\n}\n\n.ingest-metrics span {\n  color: var(--ingest-muted);\n  font: 0.7rem/1.2 var(--codeFont);\n  letter-spacing: 0.03em;\n}\n\n.ingest-metrics strong {\n  font: 650 1.65rem/1 var(--codeFont);\n}\n\n.ingest-workspace {\n  display: grid;\n  grid-template-columns: minmax(0, 1.35fr) minmax(330px, 0.65fr);\n  gap: 28px;\n  margin-top: 30px;\n}\n\n.ingest-jobs, .ingest-detail {\n  min-width: 0;\n}\n\n.ingest-section-heading {\n  display: flex;\n  align-items: end;\n  justify-content: space-between;\n  gap: 18px;\n  margin-bottom: 12px;\n}\n\n.ingest-section-heading h2, .ingest-detail h2, .ingest-publish h2 {\n  font-size: 1.15rem;\n  letter-spacing: -0.02em;\n}\n\n.ingest-section-heading label {\n  display: grid;\n  gap: 4px;\n  color: var(--ingest-muted);\n  font-size: 0.68rem;\n}\n\n.ingest-section-heading select {\n  min-height: 34px;\n  border: 1px solid var(--ingest-border);\n  border-radius: 0;\n  padding: 4px 28px 4px 8px;\n  color: var(--ingest-ink);\n  background: transparent;\n}\n\n.ingest-list {\n  border-top: 2px solid var(--ingest-ink);\n}\n\n.ingest-job {\n  display: grid;\n  width: 100%;\n  grid-template-columns: 120px minmax(0, 1fr) 96px;\n  align-items: center;\n  gap: 14px;\n  padding: 15px 10px;\n  border: 0;\n  border-bottom: 1px solid var(--ingest-border);\n  color: var(--ingest-ink);\n  background: transparent;\n  text-align: left;\n  cursor: pointer;\n}\n\n.ingest-job:hover, .ingest-job.is-selected {\n  background: color-mix(in srgb, var(--ingest-ink) 5%, transparent);\n}\n\n.ingest-job.is-selected {\n  box-shadow: inset 3px 0 0 var(--ingest-ink);\n}\n\n.ingest-status {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  color: var(--ingest-muted);\n  font: 650 0.72rem/1.2 var(--codeFont);\n}\n\n.ingest-status b {\n  display: inline-grid;\n  width: 24px;\n  height: 24px;\n  place-items: center;\n  border: 1px solid currentColor;\n}\n\n.ingest-status.is-running {\n  color: #8a5a00;\n}\n\n.ingest-status.is-succeeded {\n  color: #2c6e49;\n}\n\n.ingest-status.is-failed {\n  color: #a23a32;\n}\n\n.ingest-job-identity {\n  min-width: 0;\n}\n\n.ingest-job-identity strong, .ingest-job-identity small {\n  display: block;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.ingest-job-identity strong {\n  font-size: 0.88rem;\n}\n\n.ingest-job-identity small, .ingest-job time {\n  margin-top: 4px;\n  color: var(--ingest-muted);\n  font-size: 0.72rem;\n}\n\n.ingest-job time {\n  text-align: right;\n}\n\n.ingest-empty, .ingest-error {\n  padding: 24px 10px;\n  color: var(--ingest-muted);\n  border-bottom: 1px solid var(--ingest-border);\n}\n\n.ingest-error {\n  color: #a23a32;\n}\n\n.ingest-detail {\n  align-self: start;\n  padding: 20px;\n  border-top: 2px solid var(--ingest-ink);\n  background: color-mix(in srgb, var(--ingest-paper) 88%, white);\n}\n\n.ingest-detail-empty {\n  min-height: 210px;\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n}\n\n.ingest-detail-empty p, .ingest-detail-header p {\n  color: var(--ingest-muted);\n  font: 0.7rem/1.3 var(--codeFont);\n  letter-spacing: 0.06em;\n}\n\n.ingest-detail-empty span {\n  margin-top: 10px;\n  color: var(--ingest-muted);\n  font-size: 0.82rem;\n}\n\n.ingest-detail-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n  margin-bottom: 13px;\n}\n\n.ingest-detail-header p {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.ingest-detail-notice {\n  margin-top: 14px !important;\n  padding: 10px 12px;\n  border-left: 3px solid var(--ingest-muted);\n  color: var(--ingest-muted);\n  font-size: 0.8rem;\n}\n\n.ingest-detail-notice.is-succeeded {\n  border-color: #2c6e49;\n  color: #2c6e49;\n}\n\n.ingest-detail-notice.is-failed {\n  border-color: #a23a32;\n  color: #a23a32;\n}\n\n.ingest-detail-facts {\n  display: grid;\n  grid-template-columns: 78px minmax(0, 1fr);\n  margin: 18px 0 0;\n  padding: 14px 0;\n  border-block: 1px solid var(--ingest-border);\n  font-size: 0.74rem;\n}\n\n.ingest-detail-facts dt, .ingest-detail-facts dd {\n  padding: 4px 0;\n}\n\n.ingest-detail-facts dt {\n  color: var(--ingest-muted);\n}\n\n.ingest-detail-facts dd {\n  min-width: 0;\n  margin: 0;\n  overflow-wrap: anywhere;\n}\n\n.ingest-detail-section {\n  padding: 15px 0;\n  border-bottom: 1px solid var(--ingest-border);\n}\n\n.ingest-detail-section h3 {\n  font: 650 0.74rem/1.3 var(--codeFont);\n}\n\n.ingest-detail-section ul {\n  margin: 9px 0 0;\n  padding-left: 18px;\n  font-size: 0.76rem;\n}\n\n.ingest-detail-section li + li {\n  margin-top: 5px;\n}\n\n.ingest-detail-none {\n  margin-top: 7px !important;\n  color: var(--ingest-muted);\n  font-size: 0.75rem;\n}\n\n.ingest-publish {\n  display: grid;\n  grid-template-columns: 74px minmax(0, 1fr) auto;\n  align-items: center;\n  gap: 22px;\n  margin-top: 38px;\n  padding: 22px;\n  border: 1px solid var(--ingest-border);\n}\n\n.ingest-publish-code {\n  font: 700 1.1rem/1 var(--codeFont);\n}\n\n.ingest-publish span {\n  display: block;\n  max-width: 760px;\n  margin-top: 7px;\n  color: var(--ingest-muted);\n  font-size: 0.82rem;\n}\n\n.ingest-publish button {\n  min-height: 40px;\n  padding: 8px 16px;\n  border: 1px solid var(--ingest-border);\n  color: var(--ingest-muted);\n  background: transparent;\n  cursor: not-allowed;\n}\n\n@media all and (max-width: 1180px) {\n  .ingest-workspace {\n    grid-template-columns: 1fr;\n  }\n  .ingest-detail {\n    max-height: none;\n  }\n}\n@media all and (max-width: 720px) {\n  .ingest-page {\n    padding: 26px 18px 42px;\n  }\n  .ingest-header {\n    display: grid;\n  }\n  .ingest-refresh {\n    width: max-content;\n  }\n  .ingest-upload, .ingest-publish {\n    grid-template-columns: 42px minmax(0, 1fr);\n  }\n  .ingest-file-action, .ingest-publish button {\n    grid-column: 2;\n    width: max-content;\n  }\n  .ingest-upload-status {\n    grid-column: 1/-1;\n  }\n  .ingest-metrics {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n  .ingest-metrics > div:nth-child(2) {\n    border-right: 0;\n  }\n  .ingest-metrics > div:nth-child(-n+2) {\n    border-bottom: 1px solid var(--ingest-border);\n  }\n  .ingest-job {\n    grid-template-columns: 100px minmax(0, 1fr);\n  }\n  .ingest-job time {\n    display: none;\n  }\n}";

